// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Collection } from '@stdlib/types/array';

/**
* Converts an array of symbol aliases and/or shorthands to symbol shorthands.
*
* ## Notes
*
* -   If unable to resolve a shorthand for an element of the input array, the corresponding element in the output array is `null`.
*
* @param symbols - symbol aliases and/or shorthands
* @returns symbol shorthands
*
* @example
* var v = symbols2shorthands( [ 'circle', 'square' ] );
* // returns [ 'o', 's' ]
*
* v = symbols2shorthands( [ 'circle', 'beep' ] );
* // returns [ 'o', null ]
*/
declare function symbols2shorthands( symbols: Collection<string> ): Array<string | null>;


// EXPORTS //

export = symbols2shorthands;
